insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-07-28','opgelost','Meerwerk','Calculatie maken bij meerwerk werkt weer',
   'De knop "Calculatie" bij een meerwerkregel opent nu een echte, eigen calculatie die je kunt invullen. Daarna maak je daar de offerte van met de gewone lay-outkeuze. Voorheen liep dit vast omdat er meteen een lege offerte werd aangemaakt zonder gekozen sjabloon.');
